```cpp
template <typename Ring>
double Earcut<N>::signedArea(const Ring& points, const std::size_t start, const std::size_t end) {
    double sum = 0;
    for (std::size_t i = start, j = end - 1; i < end; i++) {
        sum += ((double)points[j].first - (double)points[i].first) * ((double)points[i].second + (double)points[j].second);
        j = i;
    }
    return sum;
}
