bool Earcut<N>::isEarHashed(Node* ear, const double minX, const double minY, const double invSize) {
    const Node* a = ear->prev;
    const Node* b = ear;
    const Node* c = ear->next;

    if (area(a, b, c) >= 0) return false;

    const double minTX = std::min(std::min(a->x, b->x), c->x);
    const double minTY = std::min(std::min(a->y, b->y), c->y);
    const double maxTX = std::max(std::max(a->x, b->x), c->x);
    const double maxTY = std::max(std::max(a->y, b->y), c->y);

    const int32_t minZ = zOrder(minTX, minTY, minX, minY, invSize);
    const int32_t maxZ = zOrder(maxTX, maxTY, minX, minY, invSize);

    Node* p = ear->nextZ;
    while (p && p->z <= maxZ) {
        if (p != ear->prev && p != ear->next &&
            pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->nextZ;
    }

    p = ear->prevZ;
    while (p && p->z >= minZ) {
        if (p != ear->prev && p != ear->next &&
            pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->prevZ;
    }

    return true;
}
