void Earcut<N>::earcutLinked(Node* ear, std::vector<N>& indices, const double minX, const double minY, const double invSize, int pass) {
    if (!ear) return;

    if (!pass && invSize) indexCurve(ear, minX, minY, invSize);

    Node* stop = ear;

    while (ear->prev != ear->next) {
        Node* prev = ear->prev;
        Node* next = ear->next;

        if (invSize ? isEarHashed(ear, minX, minY, invSize) : isEar(ear)) {
            indices.emplace_back(prev->i);
            indices.emplace_back(ear->i);
            indices.emplace_back(next->i);

            removeNode(ear);
            ear = next->next;
            stop = next->next;
            continue;
        }

        ear = next;

        if (ear == stop) {
            if (!pass) {
                earcutLinked(filterPoints(ear), indices, minX, minY, invSize, 1);
            } else if (pass == 1) {
                ear = cureLocalIntersections(filterPoints(ear), indices);
                earcutLinked(ear, indices, minX, minY, invSize, 2);
            } else if (pass == 2) {
                splitEarcut(ear, indices, minX, minY, invSize);
            }
            break;
        }
    }
}
