sortLinked (Simon Tatham's linked list merge sort):
```cpp
void Earcut<N>::sortLinked(Node* list) {
    std::size_t i = 0;
    std::size_t numMerges = 0;
    std::size_t inSize = 1;

    for (;;) {
        Node* p = list;
        list = nullptr;
        Node* tail = nullptr;
        numMerges = 0;

        while (p) {
            numMerges++;
            Node* q = p;
            std::size_t pSize = 0;
            for (i = 0; i < inSize; i++) {
                pSize++;
                q = q->nextZ;
                if (!q) break;
            }

            std::size_t qSize = inSize;

            while (pSize > 0 || (qSize > 0 && q)) {
                Node* e = nullptr;
                if (pSize == 0) {
                    e = q;
                    q = q->nextZ;
                    qSize--;
                } else if (qSize == 0 || !q) {
                    e = p;
                    p = p->nextZ;
                    pSize--;
                } else if (p->z <= q->z) {
                    e = p;
                    p = p->nextZ;
                    pSize--;
                } else {
                    e = q;
                    q = q->nextZ;
                    qSize--;
                }

                if (tail) tail->nextZ = e;
                else list = e;

                e->prevZ = tail;
                tail = e;
            }

            p = q;
        }

        tail->nextZ = nullptr;

        if (numMerges <= 1) return;

        inSize *= 2;
    }
}
```

