// earcut.rs — faithful Rust port of mapbox's earcut.hpp polygon triangulation.

const NULL: usize = usize::MAX;

#[derive(Clone)]
struct Node {
    i: u32,
    x: f64,
    y: f64,
    z: i32,
    prev: usize,
    next: usize,
    prev_z: usize,
    next_z: usize,
    steiner: bool,
}

pub struct Earcut {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    vertices: usize,
}

impl Earcut {
    fn new() -> Self {
        Earcut { nodes: Vec::new(), indices: Vec::new(), vertices: 0 }
    }

    fn construct_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node { i, x, y, z: 0, prev: NULL, next: NULL, prev_z: NULL, next_z: NULL, steiner: false });
        self.nodes.len() - 1
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.construct_node(i, x, y);
        match last {
            None => {
                self.nodes[p].prev = p;
                self.nodes[p].next = p;
            }
            Some(last) => {
                let last_next = self.nodes[last].next;
                self.nodes[p].next = last_next;
                self.nodes[p].prev = last;
                self.nodes[last_next].prev = p;
                self.nodes[last].next = p;
            }
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;
        let next_z = self.nodes[p].next_z;
        let prev_z = self.nodes[p].prev_z;
        if next_z != NULL { self.nodes[next_z].prev_z = prev_z; }
        if prev_z != NULL { self.nodes[prev_z].next_z = next_z; }
    }
