    fn z_order(&self, x: f64, y: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
        let mut x = ((x - min_x) * inv_size) as i32;
        let mut y = ((y - min_y) * inv_size) as i32;
        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;
        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;
        x | (y << 1)
    }
