//! Faithful Rust port of mapbox's earcut.hpp polygon triangulation algorithm
//! (ear clipping with hole bridging and z-order curve hashing fallback).
//!
//! Nodes live in a slab (`Vec<Node>`) and are referenced by index; `NULL`
//! plays the role of the C++ nullptr for the (linear) z-order links.

const NULL: usize = usize::MAX;

#[derive(Clone)]
struct Node {
    i: u32,
    x: f64,
    y: f64,
    z: i32,
    prev: usize,
    next: usize,
    prev_z: usize,
    next_z: usize,
    steiner: bool,
}

fn point_in_triangle(
    ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64, px: f64, py: f64,
) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

struct Earcut {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    vertices: usize,
}

impl Earcut {
    fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
        }
    }

    fn construct_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node {
            i,
            x,
            y,
            z: 0,
            prev: NULL,
            next: NULL,
            prev_z: NULL,
            next_z: NULL,
            steiner: false,
        });
        self.nodes.len() - 1
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.construct_node(i, x, y);
        match last {
            None => {
                self.nodes[p].prev = p;
                self.nodes[p].next = p;
            }
            Some(last) => {
                let last_next = self.nodes[last].next;
                self.nodes[p].next = last_next;
                self.nodes[p].prev = last;
                self.nodes[last_next].prev = p;
                self.nodes[last].next = p;
            }
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let next_z = self.nodes[p].next_z;
        let prev_z = self.nodes[p].prev_z;
        if prev_z != NULL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NULL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }

    // signed area of the ring segment (returns a positive sum for a ring that
    // is counter-clockwise in standard math orientation)
    fn signed_area(&self, points: &[(f64, f64)], start: usize, end: usize) -> f64 {
        let mut sum = 0.0;
        let mut j = end - 1;
        for i in start..end {
            sum += (points[j].0 - points[i].0) * (points[i].1 + points[j].1);
            j = i;
        }
        sum
    }

    // create a circular doubly linked list from polygon points in the
    // specified winding order
    fn linked_list(
        &mut self,
        points: &[(f64, f64)],
        start: usize,
        end: usize,
        clockwise: bool,
    ) -> Option<usize> {
        let mut last: Option<usize> = None;
        if clockwise == (self.signed_area(points, start, end) > 0.0) {
            for i in start..end {
                last = Some(self.insert_node(
                    (i + self.vertices) as u32,
                    points[i].0,
                    points[i].1,
                    last,
                ));
            }
        } else {
            let mut i = end;
            while i > start {
                i -= 1;
                last = Some(self.insert_node(
                    (i + self.vertices) as u32,
                    points[i].0,
                    points[i].1,
                    last,
                ));
            }
        }
        if let Some(l) = last {
            if self.equals(l, self.nodes[l].next) {
                self.remove_node(l);
                last = Some(self.nodes[l].next);
            }
        }
        last
    }

    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // signed area of a triangle (sign flipped vs. the standard cross product)
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
        (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
    }

    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let mut p = self.nodes[ear].next.next;
        while p != self.nodes[ear].prev {
            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }
        true
    }

    fn is_ear_hashed(&self, ear: usize, min_x: f64, min_y: f64, inv_size: f64) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx).min(cx);
        let min_ty = ay.min(by).min(cy);
        let max_tx = ax.max(bx).max(cx);
        let max_ty = ay.max(by).max(cy);

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty, min_x, min_y, inv_size);
        let max_z = self.z_order(max_tx, max_ty, min_x, min_y, inv_size);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        while p != NULL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;
        while p != NULL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(
        &mut self,
        ear: Option<usize>,
        min_x: f64,
        min_y: f64,
        inv_size: f64,
        pass: i32,
    ) {
        let mut ear = match ear {
            Some(e) => e,
            None => return,
        };

        // interlink polygon nodes in z-order
        if pass == 0 && inv_size != 0.0 {
            self.index_curve(ear, min_x, min_y, inv_size);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if inv_size != 0.0 {
                self.is_ear_hashed(ear, min_x, min_y, inv_size)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                // try filtering points and slicing again
                if pass == 0 {
                    let filtered = self.filter_points(ear, None);
                    self.earcut_linked(Some(filtered), min_x, min_y, inv_size, 1);
                // if this didn't work, try curing all small self-intersections locally
                } else if pass == 1 {
                    let filtered = self.filter_points(ear, None);
                    ear = self.cure_local_intersections(filtered);
                    self.earcut_linked(Some(ear), min_x, min_y, inv_size, 2);
                // as a last resort, try splitting the remaining polygon into two
                } else if pass == 2 {
                    self.split_earcut(ear, min_x, min_y, inv_size);
                }
                break;
            }
        }
    }

    // link every hole into the outer loop, producing a single-ring polygon without holes
    fn eliminate_holes(&mut self, points: &[Vec<(f64, f64)>], outer_node: usize) -> usize {
        let mut queue = Vec::new();
        for i in 1..points.len() {
            let end = points[i].len();
            if let Some(list) = self.linked_list(&points[i], 0, end, false) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
            self.vertices += end;
        }
        queue.sort_by(|a, b| self.nodes[*a].x.partial_cmp(&self.nodes[*b].x).unwrap());

        // process holes from left to right
        let mut outer = outer_node;
        for q in queue {
            outer = self.eliminate_hole(q, outer);
        }
        outer
    }

    // find a bridge between vertices that connects hole with an outer ring and link it
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = match self.find_hole_bridge(hole, outer_node) {
            Some(b) => b,
            None => return outer_node,
        };

        let bridge_reverse = self.split_polygon(bridge, hole);

        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, Some(br_next));
        let b_next = self.nodes[bridge].next;
        self.filter_points(bridge, Some(b_next))
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;

        // find a segment intersected by a ray from the hole's leftmost point to the left;
        // segment's endpoint with lesser x will be potential connection point
        loop {
            let pn = self.nodes[p].next;
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (nx, ny) = (self.nodes[pn].x, self.nodes[pn].y);
            if hy <= py && hy >= ny && ny != py {
                let x = px + (hy - py) * (nx - px) / (ny - py);
                if x <= hx && x > qx {
                    qx = x;
                    m = Some(if px < nx { p } else { pn });
                    if x == hx {
                        return m; // hole touches outer segment; pick leftmost endpoint
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        let mut m = m?;

        // look for points inside the triangle of hole point, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the point of the minimum angle with the ray as connection point
        let stop = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;
        let mut tan_min = f64::INFINITY;

        p = m;
        loop {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential
                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x
                                || (px == self.nodes[m].x && self.sector_contains_sector(m, p)))))
                {
                    m = p;
                    tan_min = tan;
                }
            }
            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        Some(m)
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize, min_x: f64, min_y: f64, inv_size: f64) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y, min_x, min_y, inv_size);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z;
        self.nodes[prev_z].next_z = NULL;
        self.nodes[p].prev_z = NULL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, mut list: usize) -> usize {
        let mut in_size = 1usize;

        loop {
            let mut p = list;
            list = NULL;
            let mut tail = NULL;
            let mut num_merges = 0;

            while p != NULL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NULL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NULL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NULL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NULL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NULL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x: f64, y: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x - min_x) * inv_size) as i32;
        let mut y = ((y - min_y) * inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;
        self.nodes[a_next].i != self.nodes[b].i
            && self.nodes[a_prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(a_prev, a, b_prev) != 0.0
                    || self.area(a, b_prev, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(a_prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0))
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        if self.area(self.nodes[a].prev, a, self.nodes[a].next) < 0.0 {
            self.area(a, b, self.nodes[a].next) >= 0.0
                && self.area(a, self.nodes[a].prev, b) >= 0.0
        } else {
            self.area(a, b, self.nodes[a].prev) < 0.0
                || self.area(a, self.nodes[a].next, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (x1, y1) = (self.nodes[p].x, self.nodes[p].y);
            let (x2, y2) = (self.nodes[pn].x, self.nodes[pn].y);
            if (y1 > py) != (y2 > py)
                && y2 != y1
                && (px < (x2 - x1) * (py - y1) / (y2 - y1) + x1)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    // link two polygon vertices with a bridge; if the vertices belong to the same
    // ring, it splits polygon into two; if one belongs to the outer ring and another
    // to a hole, it merges it into a single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.construct_node(ai, ax, ay);
        let b2 = self.construct_node(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, end: Option<usize>) -> usize {
        let mut end = end.unwrap_or(start);

        let mut p = start;
        loop {
            let mut again = false;

            let p_next = self.nodes[p].next;
            let p_prev = self.nodes[p].prev;
            if !self.nodes[p].steiner
                && (self.equals(p, p_next) || self.area(p_prev, p, p_next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = p_next;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                let p_next = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, None)
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize, min_x: f64, min_y: f64, inv_size: f64) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let a = self.filter_points(a, Some(a_next));
                    let c_next = self.nodes[c].next;
                    let c = self.filter_points(c, Some(c_next));

                    // run earcut on each half
                    self.earcut_linked(Some(a), min_x, min_y, inv_size, 0);
                    self.earcut_linked(Some(c), min_x, min_y, inv_size, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    fn run(&mut self, points: &[Vec<(f64, f64)>]) {
        self.indices.clear();
        self.nodes.clear();
        self.vertices = 0;

        let has_holes = points.len() > 1;
        let outer_len = points[0].len();

        let mut outer_node = self.linked_list(&points[0], 0, outer_len, true);
        self.vertices = outer_len;

        let on = match outer_node {
            Some(on) => on,
            None => return,
        };
        if self.nodes[on].prev == self.nodes[on].next {
            return;
        }

        let mut min_x = 0.0;
        let mut min_y = 0.0;
        let mut inv_size = 0.0;

        if has_holes {
            outer_node = Some(self.eliminate_holes(points, on));
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        if points[0].len() > 80 {
            min_x = points[0][0].0;
            let mut max_x = points[0][0].0;
            min_y = points[0][0].1;
            let mut max_y = points[0][0].1;

            for i in 1..outer_len {
                let x = points[0][i].0;
                let y = points[0][i].1;
                if x < min_x {
                    min_x = x;
                }
                if y < min_y {
                    min_y = y;
                }
                if x > max_x {
                    max_x = x;
                }
                if y > max_y {
                    max_y = y;
                }
            }

            // min_x, min_y and inv_size are later used to transform coords into
            // integers for z-order calculation
            inv_size = (max_x - min_x).max(max_y - min_y);
            inv_size = if inv_size != 0.0 {
                32767.0 / inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, min_x, min_y, inv_size, 0);
    }
}

/// Triangulate the given polygon (outer ring followed by hole rings).
/// Returns flattened triangle vertex indices, in the exact order the
/// reference C++ implementation emits them.
pub fn earcut(polygon: &[Vec<(f64, f64)>]) -> Vec<u32> {
    let mut e = Earcut::new();
    if !polygon.is_empty() && polygon[0].len() >= 2 {
        e.run(polygon);
    }
    e.indices
}

mod earcut;

use std::io::Write;

/// Replicates C `atoi` semantics: skip leading whitespace, optional sign,
/// then decimal digits; stops at the first non-digit; no digits -> 0.
fn atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        if b[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = val.wrapping_mul(10).wrapping_add((b[i] - b'0') as i64);
        i += 1;
    }
    sign.wrapping_mul(val) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 2;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let nf = n as f64;
    let mut polygon: Vec<Vec<(f64, f64)>> = Vec::new();
    polygon.push(vec![(0.0, 0.0), (nf, 0.0), (nf, nf), (0.0, nf)]);
    if n > 1 {
        polygon.push(vec![
            (0.25 * nf, 0.25 * nf),
            (0.75 * nf, 0.25 * nf),
            (0.75 * nf, 0.75 * nf),
            (0.25 * nf, 0.75 * nf),
        ]);
    }

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for i in indices {
        print!("{} ", i);
    }
    out.flush().unwrap();
}

